6	const neighbors = (x: number, y: number): Cell[] => {
7	  const result: Cell[] = [];
8	  for (let dx = -1; dx <= 1; dx++) {
9	    for (let dy = -1; dy <= 1; dy++) {
10	      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
11	    }
12	  }
13	  return result;
14	};
