16	/**
17	 * Tallies, for every cell adjacent to at least one live cell, how many live
18	 * neighbors it has. Cells absent from the tally have zero live neighbors and
19	 * so can never be alive next generation.
20	 */
21	const countLiveNeighbors = (cells: Cell[]): Map<string, [Cell, number]> => {
22	  const tally = new Map<string, [Cell, number]>();
23	  for (const [x, y] of cells) {
24	    for (const [nx, ny] of neighbors(x, y)) {
25	      const neighborKey = key(nx, ny);
26	      const [, count] = tally.get(neighborKey) ?? [[nx, ny], 0];
27	      tally.set(neighborKey, [[nx, ny], count + 1]);
28	    }
29	  }
30	  return tally;
31	};
