34	  const living = new Set(cells.map(([x, y]) => key(x, y)));
35	
36	  const nextCells: Cell[] = [];
37	  for (const [cellKey, [cell, count]] of countLiveNeighbors(cells)) {
38	    const isAlive = living.has(cellKey);
39	    if (count === 3 || (isAlive && count === 2)) nextCells.push(cell);
40	  }
41	  return nextCells;
42	}
